insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0001-0000-4000-8000-00000000000a', 'en', null, 'Logic & Critical Thinking', 'Learn to build, test, and take apart arguments — from premises and conclusions to truth tables and the fallacies that trip everyone up. Structure adapted from OpenStax Introduction to Philosophy (CC BY 4.0).', null, 'foundations', 10, true, 'math', '{}')
