insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0001-0000-4000-8000-00000000000a', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In logic, an argument is best defined as…","options":["any heated disagreement","a set of premises offered in support of a conclusion","a strongly held opinion","a question and its answer"],"answer":1,"explanation":"An argument is premises supporting a conclusion — not a quarrel. See ''What is an argument?''."},{"prompt":"The statement an argument is trying to establish is called the…","options":["premise","conclusion","assumption","inference"],"answer":1,"explanation":"The conclusion is the claim; premises are the support. See ''Premises and conclusions''."},{"prompt":"An argument is valid when…","options":["its premises are actually true","the conclusion is popular","if the premises were true, the conclusion would have to be true","it sounds convincing"],"answer":2,"explanation":"Validity is about form: true premises would force a true conclusion. See ''Validity vs soundness''."},{"prompt":"A sound argument is one that is…","options":["any valid argument","valid AND has all true premises","merely persuasive","one with a true conclusion, however reached"],"answer":1,"explanation":"Soundness = valid + all premises true. See ''Validity vs soundness''."},{"prompt":"Deductive reasoning aims for conclusions that are…","options":["probably true","necessarily true if the premises are true","always false","purely statistical"],"answer":1,"explanation":"Deduction targets necessity; induction targets probability. See ''Deductive vs inductive''."},{"prompt":"''Every swan I''ve seen is white, so the next one will probably be white'' is…","options":["deductive","inductive","valid by form alone","a contradiction"],"answer":1,"explanation":"It generalizes from observations to a likely conclusion — induction. See ''Deductive vs inductive''."},{"prompt":"In a truth table, ''P AND Q'' is true…","options":["when at least one is true","only when both P and Q are true","only when both are false","in every row"],"answer":1,"explanation":"Conjunction needs both conjuncts true. See ''Truth tables''."},{"prompt":"Attacking the person instead of their argument is the fallacy of…","options":["straw man","ad hominem","false dilemma","slippery slope"],"answer":1,"explanation":"Ad hominem targets the arguer, not the argument. See ''Common fallacies''."}]}'::jsonb, null, 10),
  (2, 'Arguments: premises and conclusions', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Identify an argument, separate its premises from its conclusion, and rewrite it in standard form. Warm-up: from the diagnostic, which word — ''because'' or ''therefore'' — signals a conclusion is coming?"},{"heading":"The idea","text":"An *argument* is a group of statements where some (the *premises*) are offered as reasons to accept another (the *conclusion*). Not every string of sentences is an argument: a description or a warning gives no reasons. The trick is to find the conclusion first — the point the speaker wants you to believe — then ask ''what''s offered in support?'' Signal words help: ''therefore'', ''so'', and ''hence'' usually precede a conclusion, while ''because'', ''since'', and ''for'' usually precede a premise."},{"heading":"Worked example","text":"Take: ''Since the streets are wet and it wasn''t raining, the sprinklers must have run.'' Conclusion (after ''must''): the sprinklers ran. Premises (after ''since''): the streets are wet; it wasn''t raining. In standard form — Premise 1: The streets are wet. Premise 2: It did not rain. Conclusion: Therefore, the sprinklers ran."},{"heading":"Your turn","text":"For each, name the conclusion. (1) ''You should sleep more, because tired drivers cause crashes.'' (2) ''It''s a mammal, so it breathes air.'' (3) ''The library is closed; therefore we can''t return the book today.'' (4) ''She trained daily and ate well, so she recovered quickly.'' Answers: (1) You should sleep more. (2) It breathes air. (3) We can''t return the book today. (4) She recovered quickly."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating any paragraph as an argument — a story or a set of instructions offers no reasons for a claim. Mistake: assuming the last sentence is always the conclusion (it often isn''t). Exit: (a) What is a premise? (b) Does ''because'' introduce a premise or a conclusion? Answers: a reason offered in support of the conclusion; a premise."}]}'::jsonb, 'Conclusion indicators: ''therefore'', ''so'', ''thus'', ''hence''. Premise indicators: ''because'', ''since'', ''given that''.', 12),
  (3, 'Validity versus soundness', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell a valid argument from a sound one, and show that validity alone does not make an argument''s premises true. Warm-up: can an argument be valid yet have a false conclusion?"},{"heading":"The idea","text":"*Validity* is a property of an argument''s structure: an argument is valid when it is impossible for the premises to be true and the conclusion false at the same time. Validity says nothing about whether the premises are actually true. *Soundness* adds that missing piece: an argument is sound when it is both valid AND all of its premises are in fact true. Every sound argument is valid, but most valid arguments are not sound."},{"heading":"Worked example","text":"Consider: ''All fish can fly. A salmon is a fish. Therefore a salmon can fly.'' The form is perfect — if the premises were true, the conclusion could not be false — so it is *valid*. But premise one is false, so it is *unsound*. Contrast: ''All whales are mammals. Orcas are whales. So orcas are mammals.'' Same valid form, and both premises are true — so this one is *sound*."},{"heading":"Your turn","text":"Label each valid/invalid and, if valid, sound/unsound. (1) ''All squares have four sides; this is a square; so it has four sides.'' (2) ''All birds can swim; a robin is a bird; so a robin can swim.'' (3) ''Some dogs are brown; Rex is brown; so Rex is a dog.'' (4) ''All humans are mortal; Socrates is human; so Socrates is mortal.'' Answers: (1) valid and sound. (2) valid but unsound (premise 1 is false). (3) invalid (brown things needn''t be dogs). (4) valid and sound."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a true conclusion proves the argument is valid — you can reach a true conclusion by bad reasoning. Mistake: calling a persuasive argument ''sound'' without checking that the premises are true. Exit: (a) Can a valid argument have false premises? (b) What two things must hold for soundness? Answers: yes; validity plus all-true premises."}]}'::jsonb, 'Valid = good FORM. Sound = good form + TRUE premises. A valid argument can still be false-in-fact.', 12),
  (4, 'Deductive versus inductive reasoning', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Classify reasoning as deductive or inductive and use the right yardstick for each. Warm-up: which kind promises a conclusion that is only ''probably'' true?"},{"heading":"The idea","text":"*Deductive* reasoning claims the conclusion follows with necessity: if the premises are true, the conclusion cannot be false. We grade it as valid or invalid. *Inductive* reasoning claims only that the premises make the conclusion probable — generalizing from samples, predicting the future from the past, reasoning by analogy. We grade it as strong or weak, never valid. More or better evidence makes an inductive argument stronger; it never makes it airtight."},{"heading":"Worked example","text":"Deductive: ''All prime numbers greater than two are odd. 17 is a prime greater than two. So 17 is odd.'' The conclusion is locked in. Inductive: ''The sun has risen every morning in recorded history, so it will rise tomorrow.'' Overwhelmingly strong — but not guaranteed by logic alone, which is the signature of induction."},{"heading":"Your turn","text":"Deductive or inductive? (1) ''All multiples of 4 are even; 12 is a multiple of 4; so 12 is even.'' (2) ''9 of 10 reviews are five stars, so I''ll probably like it.'' (3) ''This drug helped 95% of patients, so it will likely help the next one.'' (4) ''No square is a circle; this shape is a square; so it is not a circle.'' Answers: (1) deductive. (2) inductive. (3) inductive. (4) deductive."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling a strong inductive argument ''valid'' — validity is a deductive term only. Mistake: expecting induction to give certainty; it gives probability. Exit: (a) Which type can be valid? (b) What word best fits a good inductive argument — ''certain'' or ''probable''? Answers: deductive; probable."}]}'::jsonb, 'Deduction = necessity (''must''). Induction = probability (''likely''). Judge deduction as valid/invalid, induction as strong/weak.', 11),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The conclusion of an argument is…","options":["the reason given for a claim","the claim the premises are meant to support","any sentence with ''because''","the first sentence stated"],"answer":1,"explanation":"Premises support; the conclusion is what they support."},{"prompt":"''All men are mortal; Socrates is a man; so Socrates is mortal.'' This argument is…","options":["invalid","valid but unsound","valid and sound","inductive"],"answer":2,"explanation":"Good form and both premises true — valid and sound."},{"prompt":"An argument can be valid but unsound when…","options":["its conclusion is false","at least one premise is actually false","it is persuasive","it is inductive"],"answer":1,"explanation":"Validity is form; unsoundness comes from a false premise."},{"prompt":"Which argument is deductive?","options":["''Most students passed, so you probably will.''","''All squares have four sides; this is a square; so it has four sides.''","''The last three buses were late, so this one will be too.''","''She smiled, so she''s probably happy.''"],"answer":1,"explanation":"It claims necessity, not probability — deduction."},{"prompt":"Inductive strength is a measure of…","options":["whether the form is valid","how probable the conclusion is given the premises","whether the premises are certain","how many words the argument uses"],"answer":1,"explanation":"Induction is graded strong/weak by probability."},{"prompt":"''If the premises were all true, the conclusion could still be false'' describes…","options":["a sound argument","a valid argument","an invalid argument","an inductive certainty"],"answer":2,"explanation":"That gap between true premises and a false conclusion is exactly invalidity."}]}'::jsonb, null, 8),
  (6, 'Formal logic: connectives and truth tables', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read the four basic connectives and build a truth table row by row. Warm-up: with two variables, how many rows do you think a truth table needs?"},{"heading":"The idea","text":"Formal logic strips arguments down to symbols so we can test them mechanically. The core *connectives* are: *not* (¬P) flips a truth value; *and* (P∧Q) is true only when both parts are true; *or* (P∨Q, inclusive) is true when at least one part is true; and the *conditional* (P→Q, ''if P then Q'') is true everywhere except the one case where P is true and Q is false. A *truth table* lists every combination of truth values for the variables — 2 rows for one variable, 4 for two, and 2ⁿ for n variables — and works out the value of the whole formula in each."},{"heading":"Worked example","text":"Build the table for P → Q. Two variables means 2² = 4 rows. Row 1: P=T, Q=T → T. Row 2: P=T, Q=F → F (the only false row — a true ''if'' with a false ''then''). Row 3: P=F, Q=T → T. Row 4: P=F, Q=F → T. The last two rows are true because when P is false, the conditional makes no promise, so it cannot be broken. Compare P∧Q on the same rows: T, F, F, F — true only in row 1."},{"heading":"Your turn","text":"Evaluate each. (1) P∧Q when P=T, Q=F. (2) P∨Q when P=F, Q=F. (3) ¬P when P=T. (4) P→Q when P=F, Q=F. (5) P→Q when P=T, Q=F. (6) How many rows does a truth table with three variables need? Answers: (1) F. (2) F. (3) F. (4) T. (5) F. (6) 8 (that is 2³)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading ''or'' as exclusive — in standard logic P∨Q is *inclusive*, true even when both are true. Mistake: thinking P→Q is false whenever P is false; it is actually true in every row where P is false. Exit: (a) In which single row is P→Q false? (b) How many rows for four variables? Answers: P true and Q false; 16 (2⁴)."}]}'::jsonb, 'Connectives: ¬ (not), ∧ (and), ∨ (or, inclusive), → (if…then). A conditional P→Q is false ONLY when P is true and Q is false.', 14),
  (7, 'Common fallacies and weighing evidence', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Spot and name common informal fallacies, and judge whether a source is worth trusting. Warm-up: if someone dismisses a study by mocking the scientist''s clothes, what has gone wrong with the reasoning?"},{"heading":"The idea","text":"A *fallacy* is a pattern of reasoning that looks persuasive but fails to support its conclusion. Frequent offenders: *ad hominem* (attack the arguer, not the argument), *straw man* (distort the opponent''s view, then refute the distortion), *false dilemma* (present only two options when more exist), *appeal to irrelevant authority* (cite a famous person outside their field), *circular reasoning* (assume the very thing you''re proving), and *post hoc* (treat ''after this'' as ''because of this''). Alongside fallacy-spotting, weighing evidence means checking a source''s expertise, independence, and whether other reliable sources agree."},{"heading":"Worked example","text":"Spot the fallacy: ''My opponent wants to trim the military budget, so clearly he wants to leave the country defenseless.'' Trimming a budget is not the same as abandoning all defense — the arguer swapped in an exaggerated position that''s easier to attack. That''s a *straw man*. Notice it can feel convincing precisely because knocking down the weaker version looks like a win."},{"heading":"Your turn","text":"Name the fallacy in each. (1) ''You can''t trust her data on climate — she drives an SUV.'' (2) ''Either we ban all cars or the planet is doomed.'' (3) ''The book is reliable because it says so itself.'' (4) ''I washed my car and then it rained, so washing cars causes rain.'' (5) ''A famous actor endorses this supplement, so it must work.'' Answers: (1) ad hominem. (2) false dilemma. (3) circular reasoning. (4) post hoc / false cause. (5) appeal to irrelevant authority."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking a claim is false just because a fallacy was used — bad reasoning can still land on a true conclusion by luck; the argument, not the claim, is what fails. Mistake: treating every expert citation as a fallacy — appealing to a genuine expert in their field is reasonable evidence. Exit: (a) Which fallacy distorts an opponent''s view before attacking it? (b) Name one thing to check about a source before trusting it. Answers: straw man; relevant expertise (or independence, or corroboration by other reliable sources)."}]}'::jsonb, 'A fallacy is a flaw in reasoning, not just a false claim. Name the pattern, then say why it fails to support the conclusion.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"premise","translation":"a statement offered as a reason to accept a conclusion","example":"''All men are mortal'' is a premise in the classic Socrates argument."},{"term":"conclusion","translation":"the statement an argument tries to establish from its premises","example":"''Socrates is mortal'' is the conclusion the premises support."},{"term":"validity","translation":"the property that true premises would guarantee a true conclusion","example":"Validity depends on form, not on whether the premises are actually true."},{"term":"soundness","translation":"validity plus all premises actually being true","example":"A sound argument is valid and has no false premises."},{"term":"conditional","translation":"an ''if…then'' statement, false only when the antecedent is true and the consequent false","example":"''If it rains, the ground is wet'' is a conditional, written P → Q."},{"term":"fallacy","translation":"a pattern of reasoning that fails to support its conclusion","example":"Attacking the person is the ad hominem fallacy."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The conditional P → Q is false…","options":["only when both P and Q are false","only when P is true and Q is false","whenever P is false","in every row"],"answer":1,"explanation":"A conditional breaks only on a true antecedent with a false consequent."},{"prompt":"The inclusive disjunction P ∨ Q is false…","options":["only when both P and Q are false","only when both are true","whenever P is true","never"],"answer":0,"explanation":"''Or'' fails only when neither part is true."},{"prompt":"A truth table for three variables has how many rows?","options":["3","6","8","9"],"answer":2,"explanation":"2³ = 8 combinations."},{"prompt":"''Either you support the whole plan or you hate progress'' is a…","options":["straw man","false dilemma","ad hominem","post hoc"],"answer":1,"explanation":"It offers only two options when more exist."},{"prompt":"Distorting someone''s argument into a weaker version, then refuting that, is a…","options":["false dilemma","straw man","appeal to authority","circular reasoning"],"answer":1,"explanation":"That is the straw man fallacy."},{"prompt":"''It rained after I washed the car, so washing caused the rain'' commits the fallacy of…","options":["ad hominem","post hoc (false cause)","straw man","false dilemma"],"answer":1,"explanation":"Sequence in time is mistaken for causation — post hoc."}]}'::jsonb, null, 8),
  (10, 'Applied project: analyze a real argument', 'writing', '{"sections":[{"heading":"The task","text":"Find a short real-world argument — an opinion column, an ad, a social-media post, or a paragraph from a debate — and take it apart with the tools from this course. You are not writing your own opinion; you are evaluating someone else''s reasoning."},{"heading":"Milestones","text":"1) Quote the passage and rewrite it in standard form: list the premises, then the conclusion. 2) State whether the reasoning is deductive or inductive, and judge it accordingly (valid/invalid, or strong/weak). 3) If it is meant to be deductive, say whether it is sound — are the premises actually true? 4) Name at least one fallacy or one weak/unsupported premise, and explain exactly why it fails to support the conclusion. 5) Rewrite one part to make the argument stronger."},{"heading":"Self-check rubric","text":"✔ Premises and conclusion are separated correctly in standard form. ✔ You chose the right yardstick (validity for deduction, strength for induction). ✔ Any fallacy you named matches its real definition — you explained the flaw, not just labeled it. ✔ Your improvement genuinely repairs a gap rather than restating the original. If all four hold, you''ve analyzed the argument like a logician."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0001-0000-4000-8000-00000000000a' and l.position = v.pos
);
